responses.body:
{
  "header": {
    "version": "1.0.0",
    "message_id": "{{guid}}",
    "message_ts": "{{now "yyyy-MM-dd'T'HH:mm:ss.SSSxxx"}}",
    "action": "on-search",
    "status": "succ",
    "total_count": {{len (bodyRaw 'message.search_request')}},
    "completed_count": {{len (bodyRaw 'message.search_request')}},
    "sender_id": "fr.example.org",
    "receiver_id": "{{bodyRaw 'header.sender_id'}}",
    "is_msg_encrypted": false
  },
  "message": {
    "transaction_id": "{{bodyRaw 'message.transaction_id'}}",
    "correlation_id": "{{guid}}",
    "search_response": [
      {{#each (bodyRaw 'message.search_request')}}
      {{setVar 'all' (array)}}
      {{#if this.search_criteria.reg_record_type}}{{setVar 'kind' (dataRaw 'recordTypes' this.search_criteria.reg_record_type)}}{{setVar 'type' this.search_criteria.reg_record_type}}{{else}}{{setVar 'kind' 'farmer'}}{{setVar 'type' 'spdci-extensions-dci:Farmer'}}{{/if}}
      {{#if (eq this.search_criteria.query_type 'idtype-value')}}{{setVar 'found' (dataRaw 'index' (concat @kind '_id_' this.search_criteria.query.value))}}{{else}}{{setVar 'found' (dataRaw 'index' (concat @kind '_' this.search_criteria.query_type))}}{{/if}}
      {{#if @found}}{{setVar 'all' (slice @found 0)}}{{/if}}
      {{#if this.search_criteria.sort}}{{setVar 'all' (sortBy @all this.search_criteria.sort.[0].attribute_name this.search_criteria.sort.[0].sort_order)}}{{/if}}
      {{setVar 'size' (bodyRaw (concat 'message.search_request.' @index '.search_criteria.pagination.page_size') 10)}}
      {{setVar 'page' (bodyRaw (concat 'message.search_request.' @index '.search_criteria.pagination.page_number') 1)}}
      {{#unless @kind}}
      {
        "reference_id": "{{this.reference_id}}",
        "timestamp": "{{now "yyyy-MM-dd'T'HH:mm:ss.SSSxxx"}}",
        "status": "rjct",
        "status_reason_code": "rjct.search_criteria.invalid",
        "status_reason_message": "Unknown reg_record_type, expected a Farmer, Person, Member or Group record type",
        "locale": "{{#if this.locale}}{{this.locale}}{{else}}eng{{/if}}"
      }
      {{else}}
      {{#if (eq this.search_criteria.query.value 'TOOMANY000')}}
      {
        "reference_id": "{{this.reference_id}}",
        "timestamp": "{{now "yyyy-MM-dd'T'HH:mm:ss.SSSxxx"}}",
        "status": "rjct",
        "status_reason_code": "rjct.search.too_many_records_found",
        "status_reason_message": "Too many records match the search criteria, refine the query",
        "locale": "{{#if this.locale}}{{this.locale}}{{else}}eng{{/if}}"
      }
      {{else}}
      {
        "reference_id": "{{this.reference_id}}",
        "timestamp": "{{now "yyyy-MM-dd'T'HH:mm:ss.SSSxxx"}}",
        "status": "succ",
        "data": {
          "version": "1.0.0",
          "reg_type": "ns:org:RegistryType:FR",
          "reg_record_type": "{{@type}}",
          "reg_records": {{{stringify (slice @all (multiply (subtract @page 1) @size) (multiply @page @size))}}}
        },
        "pagination": {
          "page_size": {{@size}},
          "page_number": {{@page}},
          "total_count": {{len @all}}
        },
        "locale": "{{#if this.locale}}{{this.locale}}{{else}}eng{{/if}}"
      }
      {{/if}}
      {{/unless}}{{#unless @last}},{{/unless}}
      {{/each}}
    ]
  }
}

